import { test, expect } from '@playwright/test';

test.describe('Login Form CAPTCHA - After Failed Attempts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display CAPTCHA after 3 failed login attempts', async ({ page }) => {
    // First failed attempt
    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await emailInput.fill('user@example.com');
    await passwordInput.fill('wrongpassword123');
    await loginButton.click();

    const errorMessage = page.getByText('Invalid credentials');
    await expect(errorMessage).toBeVisible();

    // Second failed attempt
    await passwordInput.fill('wrongpassword123');
    await loginButton.click();

    await expect(errorMessage).toBeVisible();

    // Third failed attempt - CAPTCHA should appear
    await passwordInput.fill('wrongpassword123');
    await loginButton.click();

    const captchaContainer = page.getByRole('region', { name: /captcha/i });
    await expect(captchaContainer).toBeVisible();

    const captchaChallenge = page.getByText(/please verify you are human/i);
    await expect(captchaChallenge).toBeVisible();

    const captchaVerifyButton = page.getByRole('button', { name: /verify/i });
    await expect(captchaVerifyButton).toBeVisible();

    // Verify email and password fields are still visible
    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();
  });

  test('should allow successful login after CAPTCHA verification', async ({ page }) => {
    // First two failed attempts
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('wrongpassword123');
    await page.getByRole('button', { name: /login/i }).click();
    await page.getByText('Invalid credentials').waitFor();

    await page.getByLabel('Password').fill('wrongpassword123');
    await page.getByRole('button', { name: /login/i }).click();
    await page.getByText('Invalid credentials').waitFor();

    // Third failed attempt - CAPTCHA appears
    await page.getByLabel('Password').fill('wrongpassword123');
    await page.getByRole('button', { name: /login/i }).click();

    const captchaContainer = page.getByRole('region', { name: /captcha/i });
    await expect(captchaContainer).toBeVisible();

    // Fill in correct credentials
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('correctpassword123');

    // Verify CAPTCHA is visible and ready
    const captchaChallenge = page.getByText(/please verify you are human/i);
    await expect(captchaChallenge).toBeVisible();

    // Click verify button
    const captchaVerifyButton = page.getByRole('button', { name: /verify/i });
    await captchaVerifyButton.click();

    // Wait for CAPTCHA verification to complete
    await page.waitForTimeout(1000);

    // Submit login form
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify successful login
    const dashboardHeader = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardHeader).toBeVisible();
    const welcomeMessage = page.getByText(/welcome back/i);
    await expect(welcomeMessage).toBeVisible();
  });
});
